h1 {
    text-align: center;
}

#sensor-data {
    margin-top: 20px;
}
```

#### JavaScript (script.js)

```javascript
const fetchSensorData = async () => {
    try {
        const response = await fetch('https://api.example.com/voc-sensor'); // Replace with your API endpoint
        if (!response.ok) {
            throw new Error('Network response was not ok');
        }
        const data = await response.json();
        updateUI(data);
