```javascript
let windows = {};

function openWindow(app) {
    if (windows[app]) {
        windows[app].style.display = 'block';
        return;
    }

    const windowDiv = document.createElement('div');
    windowDiv.className = 'window';
    windowDiv.innerHTML = `
        <div class="window-header" onmousedown="startDrag(event, '${app}')">
            ${app.charAt(0).toUpperCase() + app.slice(1)}
            <span onclick="closeWindow('${app}')" style="float:right; cursor:pointer;">X</span>
        </div>
        <div class="window-content">${getAppContent(app)}</div>
    `;
    document.getElementById('windows-container').appendChild(windowDiv);
    windows[app] = windowDiv;
    windowDiv.style.display = 'block';
    positionWindow(windowDiv);
}

function closeWindow(app) {
    if (windows[app]) {
        windows[app].style.display = 'none';
    }
}

function closeAllWindows() {
    for (let app in windows) {
        windows[app].style.display = 'none';
    }
}

function getAppContent(app) {
    switch (app) {
        case 'notepad':
            return '<textarea style="width:100%; height:100%;"></textarea>';
        case 'calculator':
            return '<input type="text" id="calc-input" placeholder="0" /><button onclick="calculate()">=</button>';
        case 'file-explorer':
            return '<div>File Explorer Content</div>';
        default:
            return '';
    }
}

function calculate() {
    const input = document.getElementById('calc-input').value;
    try {
        const result = eval(input);
        document.getElementById('calc-input').value = result;
    } catch (e) {
        alert('Invalid expression');
    }
}

function positionWindow(windowDiv) {
    windowDiv.style.left = Math.random() * (window.innerWidth - 300) + 'px';
    windowDiv.style.top = Math.random() * (window.innerHeight - 200) + 'px';
}

function startDrag(e, app) {
    const windowDiv = windows[app];
    let offsetX = e.clientX - windowDiv.getBoundingClientRect().left;
    let offsetY = e.clientY - windowDiv.getBoundingClientRect().top;

    function dragMove(event) {
        windowDiv.style.left = event.clientX - offsetX + 'px';
        windowDiv.style.top = event.clientY - offsetY + 'px';
    }

    function dragEnd() {
        document.removeEventListener('mousemove', dragMove);
        document.removeEventListener('mouseup', dragEnd);
    }

    document.addEventListener('mousemove', dragMove);
    document.addEventListener('mouseup', dragEnd);
}
```

