import android.media.ImageReader
import android.util.Log
import android.view.Surface
import androidx.camera.core.CameraCaptureSession
import androidx.camera.core.CameraCaptureSession.CaptureCallback
import androidx.camera.core.CameraCaptureSession.CaptureResult
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

class CameraCaptureHandler {

    private val requestIdCounter = AtomicInteger(0)
    private val metadataMap = ConcurrentHashMap<Int, CaptureResult>()

    private val imageReader: ImageReader = // Initialize your ImageReader
    private val captureSession: CameraCaptureSession = // Initialize your CameraCaptureSession

    init {
        imageReader.setOnImageAvailableListener(imageAvailableListener, null)
    }

    private val imageAvailableListener = ImageReader.OnImageAvailableListener { reader ->
        val image: Image? = reader.acquireLatestImage()
        if (image != null) {
            val requestId = image.format // This is just a placeholder; you should use your actual request ID logic
            val metadata = metadataMap[requestId]

            if (metadata != null) {
                // Process the image and metadata
                processImage(image, metadata)

                // Clean up
                metadataMap.remove(requestId)
            }
            image.close()
        }
    }

    private val captureCallback = object : CaptureCallback() {
        override fun onCaptureCompleted(session: CameraCaptureSession, request: CaptureRequest, result: TotalCaptureResult) {
            val requestId = requestIdCounter.incrementAndGet()
            metadataMap[requestId] = result

            // You can also log or handle the request ID if needed
            Log.d("CameraCapture", "Capture completed with request ID: $requestId")
        }
    }

    private fun processImage(image: Image, metadata: CaptureResult) {
        // Your image processing logic here
    }

    fun captureImage() {
        val requestId = requestIdCounter.incrementAndGet()
        // Create your capture request and set the necessary parameters
        // Use requestId as needed to associate with the metadata
        // e.g., captureSession.capture(captureRequest, captureCallback, null)
    }
}
```

### Key Points:
- **Unique Request ID**: Use a unique identifier for each capture request to link the image data and metadata.
- **Concurrent Data Structure**: Use `ConcurrentHashMap` to safely store and retrieve metadata in a multi-threaded environment.
- **Cleanup**: Ensure to remove entries from the map after processing to prevent memory leaks.

This approach allows you to effectively manage the asynchronous nature of the Camera2 API callbacks and ensures that you can correctly associate image data with its corresponding metadata.

Creating a simple Geometry Dash-like game in a single HTML file involves using HTML for the structure, CSS for styling, and JavaScript for the game logic. Below is a basic implementation where the player controls a square that must jump over spikes. The game will be infinite, and the player can jump by pressing the spacebar.

Here's the complete code:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Geometry Dash Replica</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB;
        }
        #gameCanvas {
            display: block;
            margin: 0 auto;
            background-color: #fff;
            border: 2px solid #000;
        }
        .spike {
            position: absolute;
            width: 20px;
            height: 20px;
            background-color: red;
            bottom: 0;
            transform: rotate(45deg);
        }
        .player {
            position: absolute;
            width: 30px;
            height: 30px;
            background-color: blue;
            bottom: 0;
            left: 50px;
        }
    </style>
</head>
<body>
    <div id="gameContainer">
        <div class="player" id="player"></div>
    </div>
    <canvas id="gameCanvas" width="800" height="400"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const player = document.getElementById('player');
        const spikes = [];
        let isJumping = false;
        let jumpHeight = 0;
        let gravity = 1;
        let score = 0;
        let gameOver = false;

        function createSpike() {
            const spike = document.createElement('div');
            spike.className = 'spike';
            spike.style.left = '800px'; // Start off-screen
            document.body.appendChild(spike);
            spikes.push(spike);
        }

        function moveSpikes() {
            for (let i = 0; i < spikes.length; i++) {
                const spike = spikes[i];
                const spikeLeft = parseInt(spike.style.left);
                if (spikeLeft < -20) {
                    spike.remove();
                    spikes.splice(i, 1);
                    i--;
                    score++;
                } else {
                    spike.style.left = (spikeLeft - 5) + 'px';
                }
            }
        }

        function jump() {
            if (!isJumping) {
                isJumping = true;
                jumpHeight = 0;
                const jumpInterval = setInterval(() => {
                    if (jumpHeight < 100) {
                        jumpHeight += 5;
                        player.style.bottom = (jumpHeight + 20) + 'px'; // 20px is the player's height
                    } else {
                        clearInterval(jumpInterval);
                        const fallInterval = setInterval(() => {
                            if (jumpHeight > 0) {
                                jumpHeight -= 5;
                                player.style.bottom = (jumpHeight + 20) + 'px';
                            } else {
                                clearInterval(fallInterval);
                                isJumping = false;
                            }
                        }, 20);
                    }
                }, 20);
            }
        }

        function checkCollision() {
            const playerRect = player.getBoundingClientRect();
            for (const spike of spikes) {
                const spikeRect = spike.getBoundingClientRect();
                if (playerRect.left < spikeRect.right && playerRect.right > spikeRect.left &&
                    playerRect.bottom > spikeRect.top) {
                    gameOver = true;
                    alert('Game Over! Your score: ' + score);
                    document.location.reload();
                }
            }
        }

        function update() {
            if (!gameOver) {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                moveSpikes();
                checkCollision();
                ctx.fillStyle = 'black';
                ctx.font = '20px Arial';
                ctx.fillText('Score: ' + score, 10, 20);
                requestAnimationFrame(update);
            }
        }

        document.addEventListener('keydown', (event) => {
            if (event.code === 'Space') {
                jump();
            }
        });

        setInterval(createSpike, 1500); // Create a new spike every 1.5 seconds
        update();
    </script>
</body>
</html>
```

### Explanation:
- **HTML Structure**: The game consists of a `div` for the player and a `canvas` for the game area.
- **CSS Styles**: Basic styles are applied to the body, player, and spikes.
- **JavaScript Logic**:
  - The game creates spikes at regular intervals and moves them across the screen.
  - The player can jump by pressing the spacebar, and gravity is simulated to bring the player back down.
  - Collision detection checks if the player hits any spikes, and if so, the game ends and displays the score.

### How to Run:
1. Copy the code above into a text editor.
2. Save the file with a `.html` extension (e.g., `geometry_dash_replica.html`).
3. Open the file in a web browser to play the game.

Feel free to modify the code to add more features, such as different levels, more obstacles, or improved graphics!

